return $input.all().map((item) => {
  const e = item.json || {};
  const now = new Date().toISOString();
  const score = Number(e.impact_score || 75);
  const locationParts = [e.venue, e.address, e.municipality, e.state].filter(Boolean);
  const messageParts = [e.impact_summary, e.road_impact, e.transit_impact, e.description].filter(Boolean);
  const alert = {
    schema_version: '1.0',
    alert_id: `EVENT_INTEL:${e.source_event_key}`,
    source: 'EVENT_INTELLIGENCE',
    source_event_id: e.source_event_key || e.event_intelligence_id,
    category: 'EVENT',
    subtype: String(e.event_type || 'REGIONAL_EVENT').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '') || 'REGIONAL_EVENT',
    status: 'ACTIVE',
    event_action: e.alert_emitted_at ? 'UPDATE' : 'NEW',
    title: e.title || 'Regional event impact',
    message: messageParts.join(' · ') || 'High-impact regional event detected.',
    priority: score >= 90 ? 5 : 4,
    county: e.county || '',
    municipality: e.municipality || '',
    location: {
      label: locationParts.join(' · '),
      address: e.address || '',
      state: e.state || '',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['event-intelligence', 'regional-event', 'high-impact'],
    click_url: e.source_url || '',
    source_url: e.source_url || '',
    observed_at: e.last_changed_at || now,
    source_updated_at: e.last_changed_at || null,
    received_at: now,
    expires_at: e.ends_at || null,
    metadata: {
      event_intelligence_id: e.event_intelligence_id,
      impact_score: score,
      impact_summary: e.impact_summary || '',
      source_name: e.source_name || '',
      starts_at: e.starts_at || null,
      ends_at: e.ends_at || null
    }
  };
  alert.search_text = [
    alert.source, alert.category, alert.subtype, alert.title, alert.message,
    e.venue, e.address, e.municipality, e.county, e.state, ...alert.tags
  ].filter(Boolean).join(' ');
  return { json: alert };
});
